async function api<T>(path:string,init?:RequestInit):Promise<T>{const r=await fetch(API+path,{credentials:'include',headers:{'Content-Type':'application/json',...init?.headers},...init});if(!r.ok){const d=await r.json().catch(()=>({}));throw new Error(d.error||'Không thể kết nối máy chủ.');}if(r.status===204)return undefined as T;return r.json();}

