 const refresh=async()=>{if(!user)return;try{const [o,p,t]=await Promise.all([api<{orders:Order[]}>('/orders'),user.role==='admin'||user.role==='manager'?api<{users:Person[]}>('/users'):api<{users:Person[]}>('/users/share-recipients'),api<{tasks:Task[]}>('/tasks')]);setOrders(o.orders);setPeople(p.users);setTasks(t.tasks);}catch(e){setError((e as Error).message);}};
