 useEffect(()=>{if(!user||user.role==='admin'||!profile||profileBusy)return;const complete=Boolean(profile.fullName&&profile.birthDate&&profile.hometown&&profile.nationalId&&profile.position&&profile.startDate&&profile.recoveryEmail);if(!complete&&page!=='Thông tin nhân viên'){setPage('Thông tin nhân viên');setNotice('Vui lòng hoàn tất hồ sơ và thêm email khôi phục trước khi tiếp tục.')}},[user,profile,profileBusy,page]);
