 const doLogin=async(e:FormEvent)=>{e.preventDefault();setError('');setAttendanceNotice(null);try{const r=await api<{user:User;attendance?:{checkedIn?:boolean;noSchedule?:boolean;alreadyCheckedIn?:boolean;firstLoginToday?:boolean;shift?:string}}>('/auth/login',{method:'POST',body:JSON.stringify(login)});setUser(r.user);if(r.user.mustChangePassword)setShowPw(true);if(r.attendance?.firstLoginToday){if(r.attendance.noSchedule)setAttendanceNotice({kind:'warning',text:'Hôm nay bạn không có lịch làm việc nên chưa được điểm danh và không cộng ca vào bảng lương.'});else if(r.attendance.checkedIn)setAttendanceNotice({kind:'success',text:`Điểm danh thành công${r.attendance.shift?` ca ${r.attendance.shift==='morning'?'sáng':'chiều'}`:''}! Hệ thống đã cộng 1 ca vào bảng lương tháng này.`});else if(r.attendance.alreadyCheckedIn)setAttendanceNotice({kind:'info',text:'Bạn đã điểm danh hôm nay rồi. Hệ thống không cộng trùng ca.'});}}catch(e){setError((e as Error).message);}};
